export declare const modernEditorialContentTheme = "/* \u884C\u5185\u5F3A\u8C03 */\n#wemd a {\n  color: #9f4828;\n  font-weight: 600;\n  text-decoration: none;\n  border-bottom: 1px solid #d59a7f;\n}\n\n#wemd strong {\n  color: #242720;\n  font-weight: 700;\n  border-bottom: 2px solid #dfa187;\n}\n\n#wemd em {\n  color: #646858;\n  font-style: italic;\n}\n\n#wemd em strong {\n  color: #242720;\n  font-weight: 700;\n  font-style: italic;\n}\n\n#wemd mark {\n  padding: 1px 4px;\n  color: #392e27;\n  background: #f1d8c9;\n}\n\n#wemd del {\n  color: #8b8d84;\n  text-decoration: line-through;\n}\n\n#wemd u {\n  text-decoration-color: #c76237;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 0.22em;\n}\n\n#wemd hr {\n  width: 84px;\n  height: 5px;\n  margin: 54px auto;\n  border: none;\n  background: #c76237;\n}\n\n/* \u56FE\u7247\u7248\u5F0F */\n#wemd figure {\n  display: flex;\n  flex-direction: column;\n  align-items: stretch;\n  margin: 40px 4px 44px 0;\n}\n\n#wemd figure a {\n  border: none;\n}\n\n#wemd img,\n#wemd figure a img {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  margin: 0 auto;\n  padding: 7px;\n  border: 1px solid #ccccc2;\n  border-radius: 1px;\n  background: #f7f6f0;\n  box-shadow: 8px 8px 0 #deddd4;\n}\n\n#wemd figcaption {\n  margin-top: 16px;\n  padding-left: 13px;\n  border-left: 3px solid #c76237;\n  color: #73766b;\n  font-size: 12px;\n  line-height: 1.65;\n  letter-spacing: 0.04em;\n  text-align: left;\n}\n\n/* \u884C\u5185\u4EE3\u7801 */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n  margin: 0 2px;\n  padding: 2px 6px;\n  border: 1px solid #d2d1c7;\n  border-radius: 2px;\n  color: #9f4828;\n  background: #f1f0e9;\n  font-family: \"SFMono-Regular\", Consolas, \"Liberation Mono\", Menlo, monospace;\n  font-size: 13px;\n  word-break: break-all;\n}\n";
